60	    /** Provided only for API client generator usage. */
61	    public AutomationAPI() {
62	        this(null);
63	    }
64	
65	    public AutomationAPI(ExtensionAutomation extension) {
66	        super();
67	        this.extension = extension;
68	        this.addApiAction(new ApiAction(ACTION_RUN_PLAN, new String[] {PARAM_FILE_PATH}));
69	        this.addApiAction(new ApiAction(ACTION_END_DELAY_JOB));
70	        this.addApiView(new ApiView(VIEW_PLAN_PROGRESS, new String[] {PARAM_PLAN_ID}));
71	    }
72	
73	    @Override
74	    public String getPrefix() {
75	        return PREFIX;
76	    }
77	
78	    @Override
79	    public ApiResponse handleApiAction(String name, JSONObject params) throws ApiException {
80	        LOGGER.debug("handleApiAction {} {}", name, params);
81	
82	        if (name.equals(ACTION_RUN_PLAN)) {
83	            try {
84	                AutomationPlan plan =
85	                        extension.loadPlan(
86	                                new File(ApiUtils.getNonEmptyStringParam(params, PARAM_FILE_PATH)));
87	                extension.registerPlan(plan);
88	
89	                if (View.isInitialised()) {
90	                    extension.displayPlan(plan);
91	                }
92	                extension.runPlanAsync(plan);
93	
94	                return new ApiResponseElement(PARAM_PLAN_ID, Integer.toString(plan.getId()));
95	            } catch (IOException | ApiException e) {
96	                throw new ApiException(Type.DOES_NOT_EXIST, e.getMessage());
97	            }
98	        } else if (name.equals(ACTION_END_DELAY_JOB)) {
99	            DelayJob.setEndJob(true);
100	            return ApiResponseElement.OK;
101	        }
102	        throw new ApiException(Type.BAD_ACTION);
103	    }
